KG42.register("edges-023bf1f8c93e709893b880e1",{"id":"S-b9a86913451a9b07","source":"KG31-b4fad0e41a945d4f","type":"conditional_on","target":"KG40-12aedc3eec573697","evidence_class":"S","scientific_acceptance":false,"relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"paper_ids":["25-p2p_ancillary_bidding"],"assertions":[{"id":"25-p2p_ancillary_bidding::v141-c-R005::E::v141-c-R005-E002","paper":"25-p2p_ancillary_bidding","rule_id":"v141-c-R005","rule_ref":"25-p2p_ancillary_bidding::v141-c-R005","record":{"edge_id":"v141-c-R005-E002","source":"coordination.price_signal","target":"bidding.supply","type":"conditional_on","constraint_ids":["v141-c-R005-C003","v141-c-R005-C004"],"evidence_ids":["v141-b-g04-E04"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R005-C003","v141-c-R005-C004"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"KG31-b4fad0e41a945d4f","target":"KG40-12aedc3eec573697","source_occurrence_id":"25-p2p_ancillary_bidding::v141-c-R005::V::coordination.price_signal","target_occurrence_id":"25-p2p_ancillary_bidding::v141-c-R005::V::bidding.supply","source_unit_id":"25-p2p_ancillary_bidding::v141-a-M01-p2p-cda::coordination.price_signal","target_unit_id":"25-p2p_ancillary_bidding::v141-a-M01-p2p-cda::bidding.supply","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Customers' decentralized ZIP price decisions during the CDA Agreement Period. | ZIP price decisions for bids and asks remaining in the order book for time slot t. | ZIP revisions of ask prices in order book t during the CDA Agreement Period. | ZIP revisions of bid prices in order book t during the CDA Agreement Period.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E15","v141-b-g04-E04"]},"active":true,"source_signature":"e5dce473ef97db2cf92710a943d04b0368ddca9dc796a9e4945a9b8d3ebf99e5","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M01-p2p-cda","source_definition":"Results of preceding bid/ask matching provide feedback for customers' ZIP bid/ask price adjustments. Scope: Customers' decentralized ZIP price decisions during the CDA Agreement Period. The successful CDA trading price provides the comparison reference for customers' subsequent ZIP bid/ask price decisions. Scope: ZIP price decisions for bids and asks remaining in the order book for time slot t. Condition: The last CDA matching was successfully made at price π_t. In this successful-matching branch, arrival of an ask conditions the downward ZIP revision of an eligible bid price toward the feed-in tariff reference. Scope: ZIP revisions of bid prices in order book t during the CDA Agreement Period. Condition: The last matching was successful and π_{b,t} \u003c= π_t at the corresponding test in the update sequence. In the unsuccessful-matching branch, arrival of an ask conditions downward ZIP revisions of ask prices toward the feed-in tariff reference. Scope: ZIP revisions of ask prices in order book t during the CDA Agreement Period. Condition: The last matching was unsuccessful. In this successful-matching branch, arrival of a bid conditions the downward ZIP revision of an eligible ask price toward the feed-in tariff reference. Scope: ZIP revisions of ask prices in order book t during the CDA Agreement Period. Condition: The last matching was successful and π_{s,t} >= π_t at the corresponding test in the update sequence. In the unsuccessful-matching branch, arrival of a bid conditions downward ZIP revisions of bid prices toward the feed-in tariff reference. Scope: ZIP revisions of bid prices in order book t during the CDA Agreement Period. Condition: The last matching was unsuccessful.","target_definition":"When local allocation leaves an ask partially unmatched, its offered quantity is updated to σ'_{s,t} = σ_{s,t} - σ_{b,t}. Scope: CDA order-book maintenance following a successful match for time slot t in the Target Time Period T. Condition: The ask is partially allocated: σ_{b,t} - σ_{s,t} \u003c 0. When the bid quantity exceeds the ask quantity in a successful CDA match, the fully allocated ask is removed from the order book. Scope: CDA order-book maintenance following a successful match for time slot t in the Target Time Period T. Condition: The matched bid quantity exceeds the ask quantity: σ_{b,t} > σ_{s,t}.","constraints":[{"constraint_id":"v141-c-R005-C003","kind":"logical","role":"core","statement":"In this successful-matching branch, arrival of an ask conditions the downward ZIP revision of an eligible bid price toward the feed-in tariff reference. Scope: ZIP revisions of bid prices in order book t during the CDA Agreement Period. Condition: The last matching was successful and π_{b,t} \u003c= π_t at the corresponding test in the update sequence.","expression":"∀ o_{b,t} in order book t: (last matching successful at π_t ∧ an ask arrived ∧ π_{b,t} ≤ π_t) ⇒ π_{b,t} ← π_{b,t} − γ·(π_{b,t} − p_t^{FiT})","formalization_origin":"source","template_id":null,"members":["coordination.price_signal","bidding.supply"],"variable_refs":["v141-c-R005-x-pi-b"],"parameter_refs":["v141-c-R005-theta-gamma","v141-c-R005-theta-p-fit","v141-c-R005-theta-pi-t"],"evidence_ids":["v141-b-g04-E04"]},{"constraint_id":"v141-c-R005-C004","kind":"logical","role":"core","statement":"In the unsuccessful-matching branch, arrival of an ask conditions downward ZIP revisions of ask prices toward the feed-in tariff reference. Scope: ZIP revisions of ask prices in order book t during the CDA Agreement Period. Condition: The last matching was unsuccessful.","expression":"∀ o_{s,t} in order book t: (last matching unsuccessful ∧ an ask arrived) ⇒ π_{s,t} ← π_{s,t} − γ·(π_{s,t} − p_t^{FiT})","formalization_origin":"source","template_id":null,"members":["coordination.price_signal","bidding.supply"],"variable_refs":["v141-c-R005-x-pi-s"],"parameter_refs":["v141-c-R005-theta-gamma","v141-c-R005-theta-p-fit"],"evidence_ids":["v141-b-g04-E04"]}],"evidence":[{"evidence_id":"v141-b-g04-E04","location":{"location_id":"src-212077b9a1-p15-c1r2__v141-a-M01-bidding","page":15,"printed_page":null,"section":"Appendix B","anchor_text":"Appendix B The bidding process of customers in the continuous double auction (CDA) The bidding proce","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-15.png","occurrence_role":"formula"},"source_text":"The bidding process of customers in the CDA process\n1: while the current time is within the Agreement Period for CDA\n2: if a bid/ask associated with the time slot t arrives at the exchange\n3: run the CDA process as shown in Appendix A;\n4: for any bid o_{b,t} in the order book t\n5: if the last matching was successfully made at the price π_t\n6: if π_{b,t} >= π_t\n7: π_{b,t} = π_{b,t} + γ·(p^{retail}_t - π_{b,t});\n8: end if\n9: if it is an ask that arrived\n10: if π_{b,t} \u003c= π_t\n11: π_{b,t} = π_{b,t} - γ·(π_{b,t} - p^{FiT}_t);\n12: end if\n13: end if\n14: else\n15: if it is a bid that arrived\n16: π_{b,t} = π_{b,t} - γ·(π_{b,t} - p^{FiT}_t);\n17: end if\n18: end if\n19: end for\n20: for any ask o_{s,t} in the order book t\n21: if the last matching was successfully made at the price π_t\n22: if π_{s,t} \u003c= π_t\n23: π_{s,t} = π_{s,t} + γ·(p^{retail}_t - π_{s,t});\n24: end if\n25: if it is a bid that arrived\n26: if π_{s,t} >= π_t\n27: π_{s,t} = π_{s,t} - γ·(π_{s,t} - p^{FiT}_t);\n28: end if\n29: end if\n30: else\n31: if it is an ask that arrived\n32: π_{s,t} = π_{s,t} - γ·(π_{s,t} - p^{FiT}_t);\n33: end if\n34: end if\n35: end for\n36: end if\n37: end while\nNote that γ is the coefficient for customers to update their bid/ask prices, and its value within (0, 1)."}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Customers' decentralized ZIP price decisions during the CDA Agreement Period. | ZIP price decisions for bids and asks remaining in the order book for time slot t. | ZIP revisions of ask prices in order book t during the CDA Agreement Period. | ZIP revisions of bid prices in order book t during the CDA Agreement Period.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E15","v141-b-g04-E04"]},"source_record":{"edge_id":"v141-c-R005-E002","source":"coordination.price_signal","target":"bidding.supply","type":"conditional_on","constraint_ids":["v141-c-R005-C003","v141-c-R005-C004"],"evidence_ids":["v141-b-g04-E04"]},"paper_scope_note":"CDA, ancillary services, and residual agreement adjustment are kept separate; arrival events, matched orders, and the next ZIP update are not variables at the same time point; reward and compensation costs are different settlement sub-items."}}],"assertion_ids":["25-p2p_ancillary_bidding::v141-c-R005::E::v141-c-R005-E002"]});
